package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;
public class NativeUiReadyDiagnosticsTest {
 @Test public void exactLabelsOnly(){assertEquals(NativeUiReadyDiagnostics.Label.LOADING_EN,NativeUiReadyDiagnostics.label("Loading"));assertEquals(NativeUiReadyDiagnostics.Label.LOADING_DOTS_EN,NativeUiReadyDiagnostics.label("Loading..."));assertEquals(NativeUiReadyDiagnostics.Label.SIGN_IN_EN,NativeUiReadyDiagnostics.label("Sign in"));assertEquals(NativeUiReadyDiagnostics.Label.ERROR_EN,NativeUiReadyDiagnostics.label("Something went wrong"));assertEquals(NativeUiReadyDiagnostics.Label.LOADING_ZH,NativeUiReadyDiagnostics.label("正在加载"));assertEquals(NativeUiReadyDiagnostics.Label.SIGN_IN_ZH,NativeUiReadyDiagnostics.label("登录"));assertEquals(NativeUiReadyDiagnostics.Label.ERROR_ZH,NativeUiReadyDiagnostics.label("出错了"));}
 @Test public void noWhitespaceCaseOrSubstringNormalization(){for(String x:new String[]{" Loading","Loading ","loading","Sign in now","出错了!","Loading…","正在加载中"})assertNull(NativeUiReadyDiagnostics.label(x));}
 @Test public void nodeCategoriesDeduplicateTextAndDescription(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node("android.webkit.WebView","Loading","Loading...");var r=a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED);assertEquals(1,r.webViews());assertEquals(1,r.loading());assertEquals(3,r.labelMask());assertFalse(r.blocked());}
 @Test public void exactClassOnly(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node("android.webkit.WebViewSubClass",null,null);a.node("android.webkit.WebView ",null,null);assertEquals(0,a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED).webViews());}
 @Test public void blockersAreIndependentOfLoading(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node(null,"登录","Something went wrong");var r=a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED);assertEquals(1,r.signIn());assertEquals(1,r.error());assertTrue(a.blocked());assertTrue(r.blocked());}
 @Test public void unknownFieldsDoNotAcquireSemantics(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node("other","search your content","waiting");var r=a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED);assertEquals(0,r.labelMask());assertEquals(0,r.searchTitles());assertFalse(r.blocked());}
 @Test public void titleCountsDeduplicateAndRemainExact(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node(null,"Search to earn","搜索以赚取");a.node(null,"Read to earn","阅读以赚取");a.node(null,"Search points","搜索积分");a.node(null,"Read to earn more","Search to earn ");var r=a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED);assertEquals(2,r.searchTitles());assertEquals(1,r.readingTitles());}
 @Test public void fractionShapeNoValuesOrArithmetic(){for(String x:new String[]{"0/30","999/1","0 / 0","1234567890/9876543210"})assertTrue(x,NativeUiReadyDiagnostics.fractionShape(x));for(String x:new String[]{"0/30 points"," 0/30","0/30 ","0//30","a/b","０/３０","0/30\n"})assertFalse(x,NativeUiReadyDiagnostics.fractionShape(x));}
 @Test public void fractionCountOncePerNode(){var a=new NativeUiReadyDiagnostics.Accumulator();a.node(null,"0/30","20/25");assertEquals(1,a.result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED).fractionShapes());}
 @Test(expected=IllegalArgumentException.class)public void countBound(){new NativeUiReadyDiagnostics.Result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED,513,0,0,0,0,0,0,0);}
 @Test(expected=IllegalArgumentException.class)public void maskMustDescribeCounts(){new NativeUiReadyDiagnostics.Result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED,0,1,0,0,0,0,0,0);}
 @Test(expected=IllegalArgumentException.class)public void noUnknownMaskBits(){new NativeUiReadyDiagnostics.Result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED,0,0,0,0,128,0,0,0);}
 @Test(expected=IllegalArgumentException.class)public void nodeBudget(){var a=new NativeUiReadyDiagnostics.Accumulator();for(int i=0;i<513;i++)a.node(null,null,null);}
}
